export const spanishLegalGuideBySlug = (slug: string) =>
  spanishLegalGuides.find((guide) => guide.slug === slug);

/** As `legalGuidesForPractice`: the practice's own guides, then general personal-injury guides, three at most. */
export const spanishLegalGuidesForPractice = (practiceKey: string) =>
  [
    ...spanishLegalGuides.filter((guide) => guide.practiceKey === practiceKey),
    ...spanishLegalGuides.filter(
      (guide) =>
        guide.practiceKey === 'personal-injury' &&
        guide.practiceKey !== practiceKey,
    ),
  ].slice(0, 3);

